  if(e.owned){try{if(!e.native.isDestroyed?.()){e.native.setVibrancy(this.app.vault.getConfig?.('translucency')?'sidebar':null);e.native.setBackgroundColor(e.background);}}catch(_){}e.owned=false;e.applied=undefined;}
